nsole.log("Promise callback (Microtask)"); // 3\n});\n\nconsole.log("End"); // 2\n'})}),"\n",(0,e.jsx)(t.p,{children:"Th\u1ee9 t\u1ef1 th\u1ef1c thi v\xe0 gi\u1ea3i th\xedch:"}),"\n",(0,e.jsx)(t.p,{children:"console.log('Start') \u0111\u01b0\u1ee3c th\u1ef1c thi ngay l\u1eadp t\u1ee9c. (Start)\nsetTimeout \u0111\u01b0\u1ee3c g\u1ecdi. H\xe0m callback c\u1ee7a n\xf3 (console.log('Timeout callback (delay 0ms)')) \u0111\u01b0\u1ee3c \u0111\u1ea9y v\xe0o Task Queue sau 0ms.\nPromise.resolve().then() \u0111\u01b0\u1ee3c g\u1ecdi. H\xe0m callback c\u1ee7a Promise (console.log('Promise callback (Microtask)')) \u0111\u01b0\u1ee3c \u0111\u1ea9y v\xe0o Microtask Queue. (Microtask Queue c\xf3 \u0111\u1ed9 \u01b0u ti\xean cao h\u01a1n Task Queue).\nconsole.log('End') \u0111\u01b0\u1ee3c th\u1ef1c thi ngay l\u1eadp t\u1ee9c. (End)\nCall Stack tr\u1ed1ng r\u1ed7ng. Event Loop b\u1eaft \u0111\u1ea7u l\xe0m vi\u1ec7c.\nEvent Loop ki\u1ec3m tra Microtask Queue tr\u01b0\u1edbc. N\xf3 t\xecm th\u1ea5y callback c\u1ee7a Promise v\xe0 \u0111\u1ea9y n\xf3 v\xe0o Call Stack.\nCallback c\u1ee7a Promise \u0111\u01b0\u1ee3c th\u1ef1c thi. (Promise callback (Microtask))\nCall Stack tr\u1ed1ng r\u1ed7ng. Event Loop ki\u1ec3m tra Microtask Queue (n\xf3 tr\u1ed1ng).\nEvent Loop ki\u1ec3m tra Task Queue. N\xf3 t\xecm th\u1ea5y callback c\u1ee7a setTimeout v\xe0 \u0111\u1ea9y n\xf3 v\xe0o Call Stack.\nCallback c\u1ee7a setTimeout \u0111\u01b0\u1ee3c th\u1ef1c thi. (Timeout callback (delay 0ms))\nK\u1ebft qu\u1ea3 \u0111\u1ea7u ra:"}),"\n",(0,e.jsx)(t.p,{children:'Start\nEnd\nPromise callback (Microtask)\nTimeout callback (delay 0ms)\nKhi n\xe0o n\xean s\u1eed d\u1ee5ng setTimeout(fn, 0)?\nPh\xe2n t\xe1ch logic d\xe0i th\xe0nh c\xe1c ph\u1ea7n nh\u1ecf h\u01a1n (Yielding to the Event Loop): N\u1ebfu b\u1ea1n c\xf3 m\u1ed9t h\xe0m \u0111\u1ed3ng b\u1ed9 r\u1ea5t d\xe0i l\xe0m t\u1eafc ngh\u1ebdn UI, b\u1ea1n c\xf3 th\u1ec3 chia n\xf3 th\xe0nh c\xe1c ph\u1ea7n nh\u1ecf h\u01a1n v\xe0 ch\u1ea1y ch\xfa